/bin/zsh -lc "ffprobe -v error -select_streams v:0 -show_entries stream=codec_name,width,height,r_frame_rate -show_entries format=duration,size -of json video.mp4; file video.mp4; DEV_BROWSER_ISOLATED=1 dev-browser <<'EOF'
const page = await browser.getPage(\"lumail-player\");
await page.goto(\"file:///private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.dOqP7T/app/index.html\");
await page.waitForSelector(\"video\");
await page.waitForFunction(() => document.querySelector(\"video\").readyState >= 1);
const before = await page.evaluate(() => ({title: document.title, controls: document.querySelector(\"video\").controls, width: document.querySelector(\"video\").videoWidth, height: document.querySelector(\"video\").videoHeight, duration: document.querySelector(\"video\").duration}));
const playback = await page.evaluate(async () => { const v = document.querySelector(\"video\"); await v.play(); await new Promise(resolve => setTimeout(resolve, 1400)); const state = {currentTime: v.currentTime, paused: v.paused, error: v.error?.message || null}; v.pause(); return state; });
console.log(JSON.stringify({before, playback, url: await page.url()}));
EOF"

